import {ArrowRight,Plus,Store} from 'lucide-react';
import NetworkScene from './NetworkScene';
import ImageUpload from './ImageUpload';
import {useState} from 'react';
import {Drawer,Field,Form,Status} from './ui';
import {Blank,Feedback,Section} from './common';
import {platform,useResource,money} from './data';
export default function Manager({user}){
 const r=useResource(async()=>{const [organizations,addresses]=await Promise.all([platform('/organizations'),platform('/addresses')]);return{...organizations,...addresses};}),[create,setCreate]=useState(false),[selection,setSelection]=useState(''),[editStore,setEditStore]=useState(false);
 const mine=r.data?.organizations.filter(o=>o.owner_id===user.id)??[],org=mine.find(o=>o.id===selection)??mine[0];
 return <><section className="manager-hero"><div className="hero-copy"><h1>Your storefront.<br/><span>Ready for what’s next.</span></h1><p>Manage your organization, products, and incoming orders in one place.</p><button className="primary" onClick={()=>setCreate(true)}>Register organization <ArrowRight size={17}/></button></div><div className="hero-visual"><NetworkScene compact/></div></section><Feedback resource={r}/>{r.data?<>{mine.length?<><section className="store-profile"><div className="store-profile-main">{org.logo?<img className="store-logo" src={org.logo} alt={`${org.name} logo`}/>:<span className="organization-logo"><Store size={28}/></span>}<div><div className="business-selector"><label>Organization<select aria-label="Organization" value={org.id} onChange={e=>setSelection(e.target.value)}>{mine.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select></label><Status value={org.status==='approved'?'active':org.status}/></div>{org.about?<p>{org.about}</p>:null}</div></div><button className="secondary" onClick={()=>setEditStore(true)}>Edit storefront</button></section>{org.status!=='approved'?<div className="verification"><div><h3>{org.status==='pending'?'Your application is under review.':`Your organization is ${org.status}.`}</h3><p>Product publishing and dispatch require platform approval. Verification does not happen automatically.</p></div></div>:null}<Products key={org.id} organization={org}/></>:<Section title="Your organizations"><Blank title="Start with your organization.">Create your storefront and start publishing products. Solo operators and organizations use the same owner workspace.</Blank></Section>}</>:null}{editStore&&org?<Drawer title="Edit storefront" onClose={()=>setEditStore(false)}><Form submit="Save storefront" onSubmit={async d=>{await platform(`/organizations/${org.id}`,'PATCH',d);setEditStore(false);await r.refresh();}}><Field label="Organization name" name="name" required maxLength={120} defaultValue={org.name}/><ImageUpload label="Organization logo" name="logo" value={org.logo}/><Field label="About"><textarea name="about" maxLength={1000} defaultValue={org.about}/></Field><Field label="Support contact" name="support" maxLength={254} defaultValue={org.support}/></Form></Drawer>:null}{create?<Drawer title="Register your organization" onClose={()=>setCreate(false)}><p className="muted">Create your organization and start your store immediately. License details are optional and are not a verification badge.</p><Form submit="Create storefront" onSubmit={async d=>{const result=await platform('/organizations','POST',d);setSelection(result.id);setCreate(false);await r.refresh();}}><Field label="Organization name" name="name" required maxLength={120}/><ImageUpload label="Organization logo" name="logo"/><Field label="About your organization"><textarea name="about" required maxLength={1000}/></Field><Field label="Business license or registration number (optional)" name="license" maxLength={500}/><Field label="Support contact" name="support" required maxLength={254}/>{!r.data?.addresses.length?<Field label="Organization country"><select name="country">{[['NG','Nigeria'],['GH','Ghana'],['GB','United Kingdom'],['US','United States'],['MA','Morocco'],['KE','Kenya'],['FR','France'],['DE','Germany']].map(([code,name])=><option key={code} value={code}>{name}</option>)}</select></Field>:null}<p className="small muted">When available, your store uses the country saved with your account’s delivery address.</p></Form></Drawer>:null}</>;
}
function Products({organization}){
 const r=useResource(()=>platform(`/organizations/${organization.id}/products`),[organization.id]),[creating,setCreating]=useState(false),[editing,setEditing]=useState(null);
 return <><Feedback resource={r}/>{r.data?<Section title="Product catalog" action={<button className="primary" disabled={organization.status!=='approved'} onClick={()=>setCreating(true)}><Plus size={16}/>Add product</button>}><div className="catalog-summary"><div><span>Products</span><strong>{r.data.products.length}</strong></div><div><span>In stock</span><strong>{r.data.products.filter(p=>p.stock>0).length}</strong></div><div><span>Out of stock</span><strong>{r.data.products.filter(p=>!p.stock).length}</strong></div></div><div className="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th><span className="sr-only">Action</span></th></tr></thead><tbody>{r.data.products.map(p=><tr key={p.id}><td><strong>{p.name}</strong></td><td>{money(p.price_minor,p.currency)}</td><td>{p.stock}</td><td><button className="text-button" disabled={organization.status!=='approved'} onClick={()=>setEditing(p)}>Edit product</button></td></tr>)}</tbody></table>{!r.data.products.length?<Blank title="No products published yet.">Add product photos, descriptions, prices, and available stock.</Blank>:null}</div></Section>:null}{editing?<Drawer title="Update product" onClose={()=>setEditing(null)}><Form submit="Save product" onSubmit={async d=>{await platform(`/products/${editing.id}`,'PATCH',{name:d.name,priceMinor:Math.round(Number(d.price)*100),stock:Number(d.stock),image:d.image,description:d.description});setEditing(null);await r.refresh();}}><Field label="Product name" name="name" required maxLength={120} defaultValue={editing.name}/><ImageUpload label="Product photo" name="image" value={editing.image}/><Field label="Description"><textarea name="description" maxLength={2000} defaultValue={editing.description}/></Field><Field label={`Price (${editing.currency})`} name="price" type="number" min="0.01" step="0.01" required defaultValue={editing.price_minor/100}/><Field label="Available stock" name="stock" type="number" min="0" max="1000000" required defaultValue={editing.stock}/></Form></Drawer>:null}{creating?<Drawer title="Publish a product" onClose={()=>setCreating(false)}><Form submit="Publish product" onSubmit={async d=>{await platform(`/organizations/${organization.id}/products`,'POST',{name:d.name,priceMinor:Math.round(Number(d.price)*100),currency:d.currency,stock:Number(d.stock),image:d.image,description:d.description});setCreating(false);await r.refresh();}}><Field label="Product name" name="name" maxLength={120} required/><ImageUpload label="Product photo" name="image"/><Field label="Description"><textarea name="description" maxLength={2000}/></Field><Field label="Price" name="price" type="number" min="0.01" max="10000000" step="0.01" required/><Field label="Currency"><select name="currency">{[({NG:'NGN',GH:'GHS',GB:'GBP',US:'USD',MA:'MAD',KE:'KES',FR:'EUR',DE:'EUR'})[organization.country]].filter(Boolean).map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Available stock" name="stock" type="number" min="0" max="1000000" step="1" required/></Form></Drawer>:null}</>;
}
